// Helper function to get surgery data
export function getSurgeryData(surgerySlug: string): SurgeryData | undefined {
  return surgeriesData[surgerySlug];
}

// Helper function to get all surgeries
export function getAllSurgeries(): SurgeryData[] {
  return Object.values(surgeriesData);
}
